#!/usr/bin/env python3
"""amd_check.py -- diff tinybendygrad/runtime/ops_amd.bend's printed rows against
CPython. Every row the .bend prints must either

  * match a row in `.agents/slop/amd_oracle.txt` (generated by CALLING CPython), or
  * be one of the NAMED rows that are deliberately NOT CPython claims
    (`amd_init_*`, `amd_refuse_*`, `amd_pack_n_*`, `amd_arg_walrus_raw`, ...),
    each of which must be listed in `NOT_CPYTHON` below with its reason.

Usage: python3 .agents/slop/amd_check.py [bend_out.txt]
"""
import sys, os, re

