def main():
    f = sys.argv[1] if len(sys.argv) > 1 else '/tmp/amd_interp.txt'
    got = {}
    order = []
    for line in open(f):
        line = line.rstrip('\n')
        if '=' not in line: continue
        k, v = line.split('=', 1)
        got[k] = v; order.append(k)
    want = {}
    for line in open(ORACLE):
        line = line.rstrip('\n')
        if '=' not in line: continue
        k, v = line.split('=', 1)
        want[k] = v
    bad = []
    for k in order:
        if k in want:
            # `Bool.show` and `int(bool)` are the SAME claim in two renderings,
            # so the comparison normalises the two Bool spellings to 0/1. Every
            # other difference is reported as a diff.
            w = '1' if want[k] == 'True' else '0' if want[k] == 'False' else want[k]
            g = '1' if got[k] == 'True' else '0' if got[k] == 'False' else got[k]
            if w != g: bad.append((k, got[k], want[k]))
        elif k in NOT_CPYTHON:
            pass
        else:
            bad.append((k, got[k], 'NO ORACLE ROW AND NOT IN NOT_CPYTHON'))
    print(f"rows printed: {len(order)}   oracle rows: {len(want)}   mismatches: {len(bad)}")
    for k, g, w in bad:
        print(f"  MISMATCH {k}\n    bend   ={g}\n    oracle ={w}")
    unused = sorted(set(want) - set(order))
    print(f"oracle rows NOT printed by the gate: {len(unused)}")
    for u in unused: print("  unused:", u, "=", want[u])
    return 1 if bad else 0

sys.exit(main())
